import React from 'react';
import { DropDown } from '../components/DropDown';
import ChatComponent from '../components/ChatBubble';
import { ChatTextInput } from '../components/ChatTextInput';
import { ChatVoiceInput } from '../components/ChatVoiceInput';
import { NavBar } from '../components/NavBar';

const MindTalk = () => {
  return (
    <div className="flex flex-col min-h-screen">
      <div className="navbar bg-base-100 shadow-sm p-5">
        <div className=''><NavBar /></div>
        <div className="navbar-start"></div>
        <h1 className="navbar-center text-5xl">MindTalk</h1>
        <div className="navbar-end">
          <DropDown />
        </div>
      </div>

      {/* Chat Area */}
      <div className="chatArea flex-1 overflow-y-auto">
        <ChatComponent />
      </div>

      {/* Input Area */}
      <div className="inputArea w-full p-4 bg-white shadow-inner">
        <div className="flex w-full items-center gap-2">
          <div className="flex-1">
            <ChatTextInput />
          </div>
            <ChatVoiceInput />
        </div>
      </div>
    </div>
  );
}

export default MindTalk